const root = $json;
const alert = root.body?.body ?? root.body ?? root;

function pushIOC(list, type, value, source) {
  if (!value) return;
  if (typeof value !== "string") value = String(value);
  value = value.trim();
  if (!value) return;

  const exists = list.some(i => i.type === type && i.value === value);
  if (!exists) list.push({ type, value, source });
}

function mapSeverity(level) {
  level = Number(level || 0);
  if (level >= 13) return "critical";
  if (level >= 10) return "high";
  if (level >= 6) return "medium";
  return "low";
}

function isIPv4(value) {
  if (!value || typeof value !== "string") return false;
  const ip = value.trim();
  if (!/^(?:\d{1,3}\.){3}\d{1,3}$/.test(ip)) return false;

  const parts = ip.split(".").map(Number);
  return parts.every(n => n >= 0 && n <= 255);
}

function isPrivateOrLocalIP(ip) {
  if (!ip || typeof ip !== "string") return true;
  ip = ip.trim();

  return (
    ip === "127.0.0.1" ||
    ip === "::1" ||
    ip === "0.0.0.0" ||
    ip.startsWith("10.") ||
    ip.startsWith("192.168.") ||
    /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(ip) ||
    ip.startsWith("169.254.")
  );
}

function normalizeDomain(value) {
  if (!value || typeof value !== "string") return null;
  const v = value.trim().toLowerCase().replace(/\.$/, "");
  return v || null;
}

function cleanUrl(url) {
  return String(url).trim().replace(/[),.;]+$/, "");
}

function getHostFromUrl(url) {
  if (!url || typeof url !== "string") return null;

  const cleaned = url.trim();

  try {
    const host = new URL(cleaned).hostname;
    if (host) return host.trim().toLowerCase();
  } catch {}

  const m = cleaned.match(/^https?:\/\/([^\/:\s]+)(?::\d{1,5})?(?:\/|$)/i);
  if (m && m[1]) {
    return m[1].trim().toLowerCase();
  }

  return null;
}

function pushDerivedHostIOC(list, host, source) {
  if (!host) return;

  if (isIPv4(host)) {
    if (!isPrivateOrLocalIP(host)) {
      pushIOC(list, "ip", host, source);
    }
  } else {
    const d = normalizeDomain(host);
    if (d) {
      pushIOC(list, "domain", d, source);
    }
  }
}

function extractDomainsFromText(text, excludedHosts = []) {
  if (!text || typeof text !== "string") return [];

  const matches = text.match(/\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b/g) || [];
  const excludedTlds = new Set([
    "exe", "dll", "sys", "bat", "cmd", "ps1", "msi", "lnk", "tmp", "dat", "log",
    "vbs", "vbe", "ini", "txt", "json", "xml", "csv", "js", "html", "css", "py",
    "webclient"
  ]);
  const excluded = new Set(excludedHosts.map(v => String(v).toLowerCase()));

  return [...new Set(matches
    .map(m => normalizeDomain(m))
    .filter(Boolean)
    .filter(d => {
      const last = d.split(".").pop();
      if (excludedTlds.has(last)) return false;
      if (excluded.has(d)) return false;
      return true;
    })
  )];
}

function extractIPsFromText(text) {
  if (!text || typeof text !== "string") return [];

  const matches = text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [];
  return [...new Set(matches.filter(isIPv4))];
}

const iocs = [];
const ruleLevel = Number(alert.rule?.level || 0);

// Hashes
pushIOC(iocs, "sha256", alert.syscheck?.sha256_after, "syscheck.sha256_after");
pushIOC(iocs, "sha1", alert.syscheck?.sha1_after, "syscheck.sha1_after");
pushIOC(iocs, "md5", alert.syscheck?.md5_after, "syscheck.md5_after");

// IPs
const candidateIPs = [
  { value: alert.data?.srcip, source: "data.srcip" },
  { value: alert.data?.dstip, source: "data.dstip" },
  { value: alert.data?.win?.eventdata?.destinationIp, source: "win.eventdata.destinationIp" },
  { value: alert.data?.win?.eventdata?.sourceIp, source: "win.eventdata.sourceIp" },
];

for (const item of candidateIPs) {
  if (item.value && isIPv4(String(item.value)) && !isPrivateOrLocalIP(String(item.value))) {
    pushIOC(iocs, "ip", item.value, item.source);
  }
}

// Domains
const structuredDomains = [
  { value: alert.data?.hostname, source: "data.hostname" },
  { value: alert.data?.win?.eventdata?.queryName, source: "win.eventdata.queryName" },
  { value: alert.data?.win?.eventdata?.destinationHostname, source: "win.eventdata.destinationHostname" },
];

for (const item of structuredDomains) {
  const d = normalizeDomain(item.value);
  if (d && d.includes(".")) pushIOC(iocs, "domain", d, item.source);
}

// URLs
const structuredUrls = [
  { value: alert.data?.url, source: "data.url" },
  { value: alert.data?.win?.eventdata?.targetUrl, source: "win.eventdata.targetUrl" },
  { value: alert.data?.win?.eventdata?.url, source: "win.eventdata.url" },
  { value: alert.data?.win?.eventdata?.destinationUrl, source: "win.eventdata.destinationUrl" },
  { value: alert.data?.win?.eventdata?.requestUrl, source: "win.eventdata.requestUrl" },
];

for (const item of structuredUrls) {
  if (!item.value) continue;
  const u = cleanUrl(item.value);
  pushIOC(iocs, "url", u, item.source);
  const host = getHostFromUrl(u);
  if (!host) continue;
  pushDerivedHostIOC(iocs, host, `derived_from_${item.source}_url`);
}

// Free Text Sources
const freeTextSources = [
  { value: alert.data?.win?.eventdata?.commandLine, source: "win.eventdata.commandLine" },
  { value: alert.data?.win?.eventdata?.parentCommandLine, source: "win.eventdata.parentCommandLine" },
];

const urlRegex = /\bhttps?:\/\/(?:(?:\d{1,3}\.){3}\d{1,3}|(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,})(?::\d{1,5})?(?:\/[^\s"'<>\\]*)?/gi;
const extractedUrlHosts = [];

for (const item of freeTextSources) {
  if (!item.value || typeof item.value !== "string") continue;
  const matches = item.value.match(urlRegex);
  if (!matches) continue;
  for (let match of matches) {
    const u = cleanUrl(match);
    pushIOC(iocs, "url", u, item.source);
    const host = getHostFromUrl(u);
    if (!host) continue;
    extractedUrlHosts.push(host);
    pushDerivedHostIOC(iocs, host, `derived_from_${item.source}_url`);
  }
}

for (const item of freeTextSources) {
  if (!item.value || typeof item.value !== "string") continue;
  const ips = extractIPsFromText(item.value);
  for (const ip of ips) {
    if (!isPrivateOrLocalIP(ip)) {
      pushIOC(iocs, "ip", ip, item.source);
    }
  }
}

const domainTextSources = [
  { value: alert.data?.win?.eventdata?.commandLine, source: "win.eventdata.commandLine" },
  { value: alert.data?.win?.eventdata?.parentCommandLine, source: "win.eventdata.parentCommandLine" },
  { value: alert.full_log, source: "full_log" },
];

for (const item of domainTextSources) {
  const domains = extractDomainsFromText(item.value, extractedUrlHosts);
  for (const d of domains) {
    pushIOC(iocs, "domain", d, item.source);
  }
}

const priority = ["sha256", "md5", "sha1", "url", "domain", "ip"];
let primary = null;
for (const p of priority) {
  const found = iocs.find(i => i.type === p);
  if (found) {
    primary = found;
    break;
  }
}


return [{
  json: {
    alert_id: alert.id || null,
    timestamp: alert.timestamp || null,

    agent_name: alert.agent?.name || "N/A",
    agent_id: alert.agent?.id || "N/A",
    agent_ip: alert.agent?.ip || null,

    rule_id: alert.rule?.id || null,
    rule_level: ruleLevel,
    rule_description: alert.rule?.description || "N/A",
    severity_label: mapSeverity(ruleLevel),

    decoder_name: alert.decoder?.name || null,
    location: alert.location || null,
    full_log: alert.full_log || "",

    process_name: alert.data?.win?.eventdata?.image || null,
    command_line: alert.data?.win?.eventdata?.commandLine || null,
    parent_process: alert.data?.win?.eventdata?.parentImage || null,
    parent_command_line: alert.data?.win?.eventdata?.parentCommandLine || null,

    path: alert.syscheck?.path || null,
    event_action: alert.syscheck?.event || null,
    value_name: alert.syscheck?.value_name || null,

    iocs,
    ioc_count: iocs.length,
    primary_ioc_type: primary?.type || null,
    primary_ioc_value: primary?.value || null,
    primary_ioc_source: primary?.source || null,

    should_search_misp: iocs.length > 0,
    should_create_alert: ruleLevel >= 7 || iocs.length > 0,

    webhook_url: root.webhookUrl || null,
    execution_mode: root.executionMode || null,

    raw_alert: alert
  }
}];

const items = $input.all().map(i => i.json);

if (items.length === 0) {
  return [];
}

// عنصر السياق العام
const contextItem =
  items.find(item =>
    item.alert_id ||
    item.rule_id ||
    item.agent_name ||
    item.full_log
  ) || items[0];

// اجمع كل IOCs القادمة من Wazuh من كل العناصر
const allIocs = [];
const iocSeen = new Set();

function pushIOC(type, value, source) {
  if (!type || !value) return;
  const t = String(type).trim().toLowerCase();
  const v = String(value).trim();
  const s = source ? String(source).trim() : null;
  if (!t || !v) return;

  const key = `${t}:${v}`;
  if (iocSeen.has(key)) return;
  iocSeen.add(key);

  allIocs.push({
    type: t,
    value: v,
    source: s
  });
}

for (const item of items) {
  // إذا iocs مصفوفة
  if (Array.isArray(item.iocs)) {
    for (const ioc of item.iocs) {
      pushIOC(ioc?.type, ioc?.value, ioc?.source);
    }
  }
  // إذا iocs object واحد
  else if (item.iocs && typeof item.iocs === "object") {
    pushIOC(item.iocs.type, item.iocs.value, item.iocs.source);
  }

  // احتياط: لو الـ Split Out جعل الـ IOC نفسها في الحقول المباشرة
  if (item.type && item.value && item.source && !item.alert_id) {
    pushIOC(item.type, item.value, item.source);
  }
}

// اجمع فقط نتائج MISP الحقيقية
const mispItems = items.filter(item =>
  item &&
  (
    item.value ||
    item.type ||
    item.comment ||
    item.Event?.info ||
    item.Tag?.[0]?.name
  )
);

const matches = mispItems.map(item => ({
  matched_ioc_value: item.value || null,
  matched_ioc_type: item.type || null,
  matched_ioc_comment: item.comment || null,
  matched_event_info: item.Event?.info || null,
  matched_tag: item.Tag?.[0]?.name || null,
  to_ids: item.to_ids ?? null
}));

const originalTimestamp =
  contextItem.raw_alert?.timestamp ||
  contextItem.timestamp ||
  null;

const ruleLevel = Number(contextItem.rule_level || 0);
const hasMispMatch = matches.length > 0;
const highSeverity = ruleLevel >= 12;

let alert_reason = "none";
if (hasMispMatch) {
  alert_reason = "misp";
} else if (highSeverity) {
  alert_reason = "severity";
}

return [{
  json: {
    ...contextItem,
    timestamp: originalTimestamp,
    iocs: allIocs,
    ioc_count: allIocs.length,
    match_count: matches.length,
    matches,
    has_misp_match: hasMispMatch,
    high_severity: highSeverity,
    alert_reason
  }
}];

const item = $json;

const tags = [
  "source:wazuh",
  "workflow:n8n",
  "high-severity",
  `rule:${item.rule_id || "unknown"}`,
  `severity:${item.severity_label || "unknown"}`,
  `decoder:${item.decoder_name || "unknown"}`
];

const lines = [];
lines.push("Critical Wazuh alert (rule level >= 12) escalated automatically.");
lines.push("");
lines.push(`Agent: ${item.agent_name || "N/A"} (${item.agent_ip || "N/A"})`);
lines.push(`Rule ID: ${item.rule_id || "N/A"}`);
lines.push(`Rule Level: ${item.rule_level ?? "N/A"}`);
lines.push(`Rule: ${item.rule_description || "N/A"}`);
lines.push(`Severity: ${item.severity_label || "N/A"}`);
lines.push(`Decoder: ${item.decoder_name || "N/A"}`);
lines.push(`Location: ${item.location || "N/A"}`);
lines.push(`Path: ${item.path || "N/A"}`);
lines.push(`Event Action: ${item.event_action || "N/A"}`);
lines.push(`Primary IOC Type: ${item.primary_ioc_type || "N/A"}`);
lines.push(`Primary IOC Value: ${item.primary_ioc_value || "N/A"}`);
lines.push("");
lines.push("Original log:");
lines.push(item.full_log || "N/A");

return [{
  json: {
    ...item,
    thehive_title: `High Severity Alert | ${item.agent_name || "N/A"} | Rule ${item.rule_id || "N/A"} | Level ${item.rule_level ?? "N/A"}`,
    thehive_description: lines.join("\n"),
    thehive_tags: [...new Set(tags)]
  }
}];

const item = $json;

const matches = Array.isArray(item.matches) ? item.matches : [];
const iocs = Array.isArray(item.iocs)
  ? item.iocs
  : (item.iocs && typeof item.iocs === "object" ? [item.iocs] : []);

function splitTags(tagString) {
  if (!tagString) return [];
  if (Array.isArray(tagString)) return tagString.filter(Boolean);
  return String(tagString)
    .split(",")
    .map(t => t.trim())
    .filter(Boolean);
}

function normalizeObservableFromIOC(ioc) {
  if (!ioc || !ioc.type || !ioc.value) return null;

  const t = String(ioc.type).toLowerCase();
  const v = String(ioc.value).trim();
  if (!v) return null;

  if (t === "ip") {
    return {
      key: `ip:${v}`,
      dataType: "ip",
      data: v,
      messages: [`Extracted from Wazuh (${ioc.source || "unknown source"})`],
      tags: ["source:wazuh"]
    };
  }

  if (t === "domain") {
    return {
      key: `domain:${v}`,
      dataType: "domain",
      data: v,
      messages: [`Extracted from Wazuh (${ioc.source || "unknown source"})`],
      tags: ["source:wazuh"]
    };
  }

  if (t === "url") {
    return {
      key: `url:${v}`,
      dataType: "url",
      data: v,
      messages: [`Extracted from Wazuh (${ioc.source || "unknown source"})`],
      tags: ["source:wazuh"]
    };
  }

  if (t === "sha256" || t === "sha1" || t === "md5") {
    return {
      key: `hash:${v}`,
      dataType: "hash",
      data: v,
      messages: [`Extracted from Wazuh (${t})`],
      tags: ["source:wazuh", `hash:${t}`]
    };
  }

  return null;
}

function normalizeObservableFromMatch(match) {
  if (!match || !match.matched_ioc_value || !match.matched_ioc_type) return null;

  const t = String(match.matched_ioc_type).toLowerCase();
  const raw = String(match.matched_ioc_value).trim();
  if (!raw) return null;

  if (t.includes("ip")) {
    const ip = raw.includes("|") ? raw.split("|")[0].trim() : raw;

    return {
      key: `ip:${ip}`,
      dataType: "ip",
      data: ip,
      messages: [
        [
          match.matched_ioc_comment,
          match.matched_event_info,
          raw !== ip ? `raw:${raw}` : null
        ].filter(Boolean).join(" | ")
      ],
      tags: [
        "source:misp",
        match.matched_tag,
        match.matched_event_info
      ].filter(Boolean)
    };
  }

  if (t.includes("domain") || t.includes("hostname")) {
    return {
      key: `domain:${raw}`,
      dataType: "domain",
      data: raw,
      messages: [[match.matched_ioc_comment, match.matched_event_info].filter(Boolean).join(" | ")],
      tags: ["source:misp", match.matched_tag, match.matched_event_info].filter(Boolean)
    };
  }

  if (t.includes("url")) {
    return {
      key: `url:${raw}`,
      dataType: "url",
      data: raw,
      messages: [[match.matched_ioc_comment, match.matched_event_info].filter(Boolean).join(" | ")],
      tags: ["source:misp", match.matched_tag, match.matched_event_info].filter(Boolean)
    };
  }

  if (t.includes("sha256") || t.includes("sha1") || t.includes("md5")) {
    return {
      key: `hash:${raw}`,
      dataType: "hash",
      data: raw,
      messages: [[match.matched_ioc_comment, match.matched_event_info].filter(Boolean).join(" | ")],
      tags: ["source:misp", match.matched_tag, match.matched_event_info, `hash:${t}`].filter(Boolean)
    };
  }

  return null;
}

const observableMap = new Map();

function upsertObservable(obs) {
  if (!obs) return;

  if (!observableMap.has(obs.key)) {
    observableMap.set(obs.key, {
      dataType: obs.dataType,
      data: obs.data,
      messages: [...new Set(obs.messages || [])],
      tags: [...new Set(obs.tags || [])]
    });
    return;
  }

  const existing = observableMap.get(obs.key);
  existing.messages = [...new Set([...(existing.messages || []), ...(obs.messages || [])])];
  existing.tags = [...new Set([...(existing.tags || []), ...(obs.tags || [])])];
  observableMap.set(obs.key, existing);
}

for (const ioc of iocs) {
  upsertObservable(normalizeObservableFromIOC(ioc));
}

for (const match of matches) {
  upsertObservable(normalizeObservableFromMatch(match));
}

const observables = Array.from(observableMap.values()).map(obs => ({
  dataType: obs.dataType,
  data: obs.data,
  message: obs.messages.join(" || "),
  tags: obs.tags.join(",")
}));

const isMispPath = (item.match_count || 0) > 0;
const isSeverityPath = !isMispPath && Number(item.rule_level || 0) >= 12;

const tags = [
  "source:wazuh",
  "workflow:n8n",
  `rule:${item.rule_id || "unknown"}`,
  `severity:${item.severity_label || "unknown"}`,
  `decoder:${item.decoder_name || "unknown"}`
];

if (isMispPath) {
  tags.push("source:misp", "misp-match");
}

if (isSeverityPath) {
  tags.push("high-severity", "severity-threshold:12");
}

for (const m of matches) {
  if (m.matched_tag) tags.push(`malware:${m.matched_tag}`);
}

const uniqueTags = [...new Set(tags)];

const lines = [];
lines.push(
  isMispPath
    ? "Wazuh alert enriched by MISP."
    : "High severity Wazuh alert escalated automatically."
);
lines.push("");
lines.push(`Agent: ${item.agent_name || "N/A"} (${item.agent_ip || "N/A"})`);
lines.push(`Rule ID: ${item.rule_id || "N/A"}`);
lines.push(`Rule Level: ${item.rule_level ?? "N/A"}`);
lines.push(`Rule: ${item.rule_description || "N/A"}`);
lines.push(`Severity: ${item.severity_label || "N/A"}`);
lines.push(`Decoder: ${item.decoder_name || "N/A"}`);
lines.push(`Location: ${item.location || "N/A"}`);
lines.push(`Path: ${item.path || "N/A"}`);
lines.push(`Event Action: ${item.event_action || "N/A"}`);
lines.push(`MISP Matches Count: ${item.match_count || 0}`);
lines.push(`Unique Observables Count: ${observables.length}`);
lines.push("");

if (matches.length > 0) {
  lines.push("Matched observables:");
  matches.forEach((m, idx) => {
    lines.push(`${idx + 1}. ${m.matched_ioc_value || "N/A"} | ${m.matched_ioc_type || "N/A"} | ${m.matched_tag || "N/A"} | ${m.matched_event_info || "N/A"}`);
  });
  lines.push("");
}

if (iocs.length > 0) {
  lines.push("Extracted IOCs:");
  iocs.forEach((ioc, idx) => {
    lines.push(`${idx + 1}. ${ioc.value || "N/A"} | ${ioc.type || "N/A"} | ${ioc.source || "N/A"}`);
  });
  lines.push("");
}

lines.push("Original log:");
lines.push(item.full_log || "N/A");

const titlePrefix = isMispPath ? "MISP Match" : "High Severity Alert";

// =========================================================================
// التعديل الجديد: توليد بصمة فريدة تمنع التكرار في نفس الدقيقة (Deduplication)
// =========================================================================
const safeTime = (item.timestamp || "").substring(0, 16).replace(/:/g, "-");
const primaryIoc = item.primary_ioc_value || item.rule_id || "Alert";
const customSourceRef = `${item.agent_name || "NA"}-${primaryIoc}-${safeTime}`;
// =========================================================================

return [{
  json: {
    ...item,
    thehive_title: `${titlePrefix} | ${item.agent_name || "N/A"} | Rule ${item.rule_id || "N/A"} | ${observables.length} unique observables`,
    thehive_description: lines.join("\n"),
    thehive_tags: uniqueTags,
    thehive_observables: observables,
    thehive_source_ref: customSourceRef // تمرير البصمة الجاهزة للخطوة التالية
  }
}];

const item = $json;

// فحص قاطع: هل التنبيه مرفوض من TheHive (يحتوي على خطأ) أو لا يمتلك ID؟
if (item.error || !item._id) {
    // إرجاع مصفوفة فارغة يجعل n8n يوقف هذا المسار بصمت تام! 
    // لن يظهر لون أحمر، ولن تنتقل البيانات للخطوة التالية.
    return [];
}

// أما إذا كان التنبيه سليماً وناجحاً، مرره للخطوة التالية
return [{ json: item }];
